import os
import pytest
from opencode_zen.config import OpenCodeZenConfig

@pytest.fixture(autouse=True)
def clear_env():
    original_env = dict(os.environ)
    os.environ.clear()
    yield
    os.environ.clear()
    os.environ.update(original_env)

def test_config_fallback_to_general_key():
    os.environ["OPENCODE_ZEN_API_KEY"] = "general-key-123"
    config = OpenCodeZenConfig()
    assert config.get_model_key("claude-fable-5") == "general-key-123"
    assert config.get_model_key("gemini-3.1-pro") == "general-key-123"

def test_config_uses_model_specific_keys():
    os.environ["OPENCODE_ZEN_API_KEY"] = "general-key-123"
    os.environ["OPENCODE_ZEN_KEY_CLAUDE_FABLE_5"] = "claude-key-456"
    os.environ["OPENCODE_ZEN_KEY_GEMINI_3_1_PRO"] = "gemini-key-789"
    
    config = OpenCodeZenConfig()
    assert config.get_model_key("claude-fable-5") == "claude-key-456"
    assert config.get_model_key("gemini-3.1-pro") == "gemini-key-789"
    assert config.get_model_key("unknown-model") == "general-key-123"


